package io.github.polestarcn.companion;
import static org.junit.Assert.*;
import io.github.polestarcn.companion.api.*;import io.github.polestarcn.companion.auth.SecureSessionStore;import io.grpc.*;
import java.lang.reflect.*;import java.util.concurrent.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28,shadows=ClimateTargetTransportV087Test.Store.class)
public class ClimateTargetTransportV087Test {
 @Implements(value=SecureSessionStore.class,isInAndroidSdk=false) public static class Store {static ChinaPolestarApi.Session value;@Implementation public static ChinaPolestarApi.Session load(android.content.Context c){return value;}@Implementation public static void save(android.content.Context c,ChinaPolestarApi.Session s){value=s;}@Implementation public static void clear(android.content.Context c){value=null;}}
 private ChinaPolestarApi api;private Channel channel;
 @Before public void setup()throws Exception{Store.value=new ChinaPolestarApi.Session();Store.value.access="fixture";Store.value.expiresAt=System.currentTimeMillis()+3600_000L;Store.value.c3Host="fixture.invalid";api=new ChinaPolestarApi(RuntimeEnvironment.getApplication());channel=new Channel();Field f=ChinaPolestarApi.class.getDeclaredField("sharedChannel");f.setAccessible(true);f.set(api,channel);f=ChinaPolestarApi.class.getDeclaredField("sharedHost");f.setAccessible(true);f.set(api,"fixture.invalid:443");}
 @Test public void selectedTemperatureIsEncodedAsTheTemplateFloat32Field()throws Exception{for(float target:new float[]{18f,22f,24f,28f}){api.climateStart("FIXTURE",target);assertEquals("invocation.InvocationService/ClimatizationStart",channel.method);java.util.Map<Integer,Object> body=ProtoWire.decode(channel.request);assertEquals(1,ProtoWire.integer(body,2).intValue());assertEquals(target,ProtoWire.decimal(body,3).floatValue(),.001f);assertEquals("FIXTURE",new String((byte[])ProtoWire.nested(body,1).get(1),java.nio.charset.StandardCharsets.UTF_8));}assertEquals(4,channel.calls);}
 @Test public void invalidTemperaturesNeverReachTransport()throws Exception{for(float v:new float[]{Float.NaN,Float.POSITIVE_INFINITY,17f,29f})try{api.climateStart("FIXTURE",v);fail("range validation");}catch(IllegalArgumentException expected){}assertEquals(0,channel.calls);}
 @Test public void rejectedTemperatureDoesNotRetryTheWrite()throws Exception{channel.fail=true;try{api.climateStart("FIXTURE",24);fail("rejection");}catch(Exception expected){}assertEquals(1,channel.calls);}
 private static final class Channel extends ManagedChannel {byte[] request;String method;int calls;boolean fail;
  @Override @SuppressWarnings("unchecked")public <Q,S> ClientCall<Q,S> newCall(MethodDescriptor<Q,S>d,CallOptions options){method=d.getFullMethodName();calls++;return new ClientCall<Q,S>(){Listener<S> listener;public void start(Listener<S>l,Metadata headers){listener=l;}public void request(int n){}public void cancel(String m,Throwable c){}public void sendMessage(Q q){request=(byte[])q;}public void halfClose(){if(fail)listener.onClose(Status.INVALID_ARGUMENT,new Metadata());else{listener.onHeaders(new Metadata());listener.onMessage((S)new byte[0]);listener.onClose(Status.OK,new Metadata());}}};}
  public String authority(){return "fixture.invalid";}public ManagedChannel shutdown(){return this;}public ManagedChannel shutdownNow(){return this;}public boolean isShutdown(){return false;}public boolean isTerminated(){return false;}public boolean awaitTermination(long t,TimeUnit u){return true;}}
}
